public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) {
        return 0; // at least one empty string so no positive-length substring possible
    }
    // Iterate from longest possible length downwards
    for (int L = minLen; L >= 1; L--) {
        Set<String> intersection = null;
        boolean failed = false;
        for (String s : strings) {
            Set<String> currentSet = new HashSet<>();
            int len = s.length();
            for (int i = 0; i + L <= len; i++) {
                String sub = s.substring(i, i + L);
                currentSet.add(sub);
                // Add reverse of the substring
                String rev = new StringBuilder(sub).reverse().toString();
                currentSet.add(rev);
            }
            if (intersection == null) {
                intersection = currentSet;
            } else {
                intersection.retainAll(currentSet);
            }
            if (intersection.isEmpty()) {
                failed = true;
                break;
            }
        }
        if (!failed && intersection != null && !intersection.isEmpty()) {
            return L;
        }
    }
    return 0; // no common substring of positive length found
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0], cc = pos[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dr[k];
                        int nc = cc + dc[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                            !visited[nr][nc] && grid[nr][nc] == '@') {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
