private static void dfsOil(int r, int c, char[][] grid, int rows, int cols) {
    // Boundary and already visited checks
    if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != '@') {
        return;
    }

    // Mark current cell as visited
    grid[r][c] = '*';

    // Explore all 8 neighboring cells
    for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
            if (dr != 0 || dc != 0) {
                dfsOil(r + dr, c + dc, grid, rows, cols);
            }
        }
    }
}

