public static int maxRegions(int N) {
    // Validate input: number of triangles cannot be negative.
    if (N <= 0) {
        return 1; // A plane with no triangles has just one region.
    }

    // The maximum number of regions created by N triangles in general position
    // follows the formula: R = 3*N^2 - 3*N + 2.
    // Use long to avoid intermediate overflow.
    long regions = 3L * N * N - 3L * N + 2L;

    // Ensure the result fits in an int. If it doesn't, throw an exception.
    if (regions > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Result exceeds the maximum value representable by an int.");
    }

    return (int) regions;
}

