public static int countDoubles(int[] numbers) {
    if (numbers == null) {
        throw new IllegalArgumentException("Input array must not be null.");
    }
    // Build frequency map to handle duplicates and zero handling
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }

    int count = 0;
    for (int num : numbers) {
        // Handle zero separately because 0*2 == 0
        if (num == 0) {
            if (freq.get(0) >= 2) {
                count++;
            }
        } else {
            long doubleVal = (long) num * 2;
            // Only if doubleVal fits into int, check existence
            if (doubleVal >= Integer.MIN_VALUE && doubleVal <= Integer.MAX_VALUE) {
                if (freq.containsKey((int) doubleVal)) {
                    count++;
                }
            }
        }
    }
    return count;
}

public static int countDoubles(int[] numbers) {
