    for (int n : numbers) {
        long doubled = (long) n * 2;
        if (doubled <= Integer.MAX_VALUE && doubled >= Integer.MIN_VALUE) {
            if (set.contains((int) doubled)) {
                count++;
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || paths == null) return "cannot be travelled";
        int dim = start.length;
        if (end.length != dim) return "cannot be travelled";
        for (int i = 0; i < dim; i++) {
            if (start[i] < 0 || start[i] >= n || end[i] < 0 || end[i] >= n) return "cannot be travelled";
        }
        if (java.util.Arrays.equals(start, end)) return "can be travelled";

        java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
        for (int[] p : paths) {
            if (p == null || p.length != 2 * dim) throw new IllegalArgumentException();
            int[] a = new int[dim];
            int[] b = new int[dim];
            System.arraycopy(p, 0, a, 0, dim);
            System.arraycopy(p, dim, b, 0, dim);
            String keyA = java.util.Arrays.toString(a);
            String keyB = java.util.Arrays.toString(b);
            adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
            adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
        }

        String startKey = java.util.Arrays.toString(start);
        String endKey = java.util.Arrays.toString(end);
        java.util.Queue<String> queue = new java.util.LinkedList<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        queue.add(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String curr = queue.poll();
            java.util.List<String> neighbors = adj.getOrDefault(curr, java.util.Collections.emptyList());
            for (String nb : neighbors) {
                if (!visited.contains(nb)) {
                    if (nb.equals(endKey)) return "can be travelled";
                    visited.add(nb);
                    queue.add(nb);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        // Validate inputs
        if (n <= 0) return "cannot be travelled";
        if (start == null || end == null) return "cannot be travelled";
        if (start.length == 0 || end.length == 0) return "cannot be travelled";
        // Assume start and end are single-indexed (first element is node id)
        int startNode = start[0];
        int endNode = end[0];
        if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
            return "cannot be travelled";
        }
        // Quick check: same node
        if (startNode == endNode) return "can be travelled";

        // Build adjacency list
        @SuppressWarnings("unchecked")
        java.util.List<Integer>[] graph = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new java.util.ArrayList<>();
        if (paths != null) {
            for (int[] edge : paths) {
                if (edge == null || edge.length < 2) continue;
                int u = edge[0];
                int v = edge[1];
                if (u < 0 || u >= n || v < 0 || v >= n) continue;
                graph[u].add(v);
                graph[v].add(u); // assume undirected paths
            }
        }

        // Breadth-first search
        boolean[] visited = new boolean[n];
        java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
        queue.offer(startNode);
        visited[startNode] = true;

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int nx : graph[cur]) {
                if (!visited[nx]) {
                    if (nx == endNode) return "can be travelled";
                    visited[nx] = true;
                    queue.offer(nx);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        // On any runtime error, return failure hint
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0 || start == null || end == null || start.length != end.length) {
        return "cannot be travelled";
    }
    int dims = start.length;
    // Helper to convert coordinates to a single integer index
    java.util.function.Function<int[], Integer> toIndex = coords -> {
        int idx = 0;
        for (int c : coords) {
            if (c < 0 || c >= n) {
                return null; // invalid coordinate
            }
            idx = idx * n + c;
        }
        return idx;
    };
    Integer startIdx = toIndex.apply(start);
    Integer endIdx = toIndex.apply(end);
    if (startIdx == null || endIdx == null) {
        return "cannot be travelled";
    }
    // Quick check if start equals end
    if (startIdx.equals(endIdx)) {
        return "can be travelled";
    }
    // Build adjacency list
    java.util.Map<Integer, java.util.List<Integer>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null) continue;
            // If path consists of two indices
            if (p.length == 2) {
                Integer u = p[0];
                Integer v = p[1];
                if (u == null || v == null) continue;
                adj.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(v);
                adj.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(u);
            } else if (p.length == dims * 2) { // path consists of two coordinate arrays concatenated
                int[] coordA = new int[dims];
                int[] coordB = new int[dims];
                System.arraycopy(p, 0, coordA, 0, dims);
                System.arraycopy(p, dims, coordB, 0, dims);
                Integer u = toIndex.apply(coordA);
                Integer v = toIndex.apply(coordB);
                if (u == null || v == null) continue;
                adj.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(v);
                adj.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(u);
            } else {
                // Invalid path entry; ignore
                continue;
            }
        }
    }
    // BFS
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    java.util.Set<Integer> visited = new java.util.HashSet<>();
    queue.offer(startIdx);
    visited.add(startIdx);
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        java.util.List<Integer> neighbors = adj.get(cur);
        if (neighbors != null) {
            for (int nb : neighbors) {
                if (!visited.contains(nb)) {
                    if (nb == endIdx) {
                        return "can be travelled";
                    }
                    visited.add(nb);
                    queue.offer(nb);
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation of inputs
    if (n <= 0) {
        throw new IllegalArgumentException("Grid size must be positive.");
    }
    if (start == null || end == null || start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Start and end coordinates must be non-null arrays of length 2.");
    }
    int startX = start[0], startY = start[1];
    int endX = end[0], endY = end[1];
    if (startX < 0 || startX >= n || startY < 0 || startY >= n ||
        endX < 0 || endX >= n || endY < 0 || endY >= n) {
        return "cannot be travelled";
    }
    int totalNodes = n * n;
    // adjacency lists
    java.util.List<int[]>[] graph = new java.util.ArrayList[totalNodes];
    for (int i = 0; i < totalNodes; i++) {
        graph[i] = new java.util.ArrayList<>();
    }

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 4) {
                throw new IllegalArgumentException("Each path must have exactly 4 integers: x1,y1,x2,y2.");
            }
            int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n ||
                x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                throw new IllegalArgumentException("Path coordinates out of bounds.");
            }
            int u = x1 * n + y1;
            int v = x2 * n + y2;
            graph[u].add(v);
            graph[v].add(u);
        }
    }

    int startIdx = startX * n + startY;
    int endIdx = endX * n + endY;

    // If start and end are the same
    if (startIdx == endIdx) {
        return "can be travelled";
    }

    // BFS
    boolean[] visited = new boolean[totalNodes];
    java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
    visited[startIdx] = true;
    queue.add(startIdx);

    while (!queue.isEmpty()) {
        int curr = queue.poll();
        for (int neighbor : graph[curr]) {
            if (!visited[neighbor]) {
                if (neighbor == endIdx) {
                    return "can be travelled";
                }
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        // Basic input validation
        if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
            return "cannot be travelled";
        }

        // If start and end are the same point, travel is trivially possible
        boolean same = true;
        for (int i = 0; i < n; i++) {
            if (start[i] != end[i]) {
                same = false;
                break;
            }
        }
        if (same) {
            return "can be travelled";
        }

        // Build adjacency list
        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

        // Helper to convert coordinate array to string key
        java.util.function.Function<int[], String> makeKey = coord -> {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < coord.length; i++) {
                if (i > 0) sb.append(',');
                sb.append(coord[i]);
            }
            return sb.toString();
        };

        String startKey = makeKey.apply(start);
        String endKey = makeKey.apply(end);

        if (paths != null) {
            for (int[] path : paths) {
                if (path == null || path.length != 2 * n) {
                    // malformed path entry, skip or treat as invalid
                    continue;
                }
                int[] p1 = new int[n];
                int[] p2 = new int[n];
                System.arraycopy(path, 0, p1, 0, n);
                System.arraycopy(path, n, p2, 0, n);
                String key1 = makeKey.apply(p1);
                String key2 = makeKey.apply(p2);

                graph.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
                graph.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
            }
        }

        // BFS to find connectivity
        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        queue.add(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String current = queue.poll();
            if (current.equals(endKey)) {
                return "can be travelled";
            }
            java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
            for (String nb : neighbors) {
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.add(nb);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // Any unexpected error results in the travel being considered impossible
        return "cannot be travelled";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return null;
    }
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return null;
        }
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        java.time.format.DateTimeFormatter monthFormatter = java.time.format.DateTimeFormatter.ofPattern("MMMM");
        String monthName = localDate.format(monthFormatter);

        java.time.format.DateTimeFormatter dayFormatter = java.time.format.DateTimeFormatter.ofPattern("d");
        String dayString = localDate.format(dayFormatter);

        java.time.format.DateTimeFormatter dayOfWeekFormatter = java.time.format.DateTimeFormatter.ofPattern("EEEE");
        String dayOfWeek = localDate.format(dayOfWeekFormatter);

        return String.format("%s %s, %d is a %s", monthName, dayString, year, dayOfWeek);
    } catch (NumberFormatException | java.time.DateTimeException e) {
        return null;
    }
}

