                    hi = mid - 1;
                }
            }
        }
    } catch (Exception e) {
        // Return -1 on any runtime exception
    }
    return -1;
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int low = 0;
    int high = nums.length - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[low] <= nums[mid]) { // left side is sorted
            if (nums[low] <= target && target < nums[mid]) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        } else { // right side is sorted
            if (target > nums[mid] && target <= nums[high]) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int k = n / 20; // floor of 5% of the array length
    if (k == 0) { // no elements to trim
        long sumAll = 0;
        for (int num : arr) {
            sumAll += num;
        }
        return (double) sumAll / n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0L;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return (double) sum / (n - 2 * k);
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    try {
        int n = arr.length;
        int removeCount = n / 20; // 5% of elements on each side
        java.util.Arrays.sort(arr);
        int start = removeCount;
        int end = n - removeCount; // exclusive
        if (start >= end) {
            return 0.0;
        }
        double sum = 0.0;
        for (int i = start; i < end; i++) {
            sum += arr[i];
        }
        return sum / (end - start);
    } catch (Exception e) {
        // In case of any unexpected runtime exception, return 0.0
        return 0.0;
    }
}

