    }
    int remaining = n - 2 * k;
    return sum / (double) remaining;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    // Use modulus with positive k
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }
    // Check pairs for remainders 1..k-1
    for (int r = 1; r < k; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    // Remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // For even k, remainder k/2 must also be even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0 || k <= 0) {
        return false; // invalid input
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // must be even number of elements for pairing
    }
    int[] remCount = new int[k];
    for (int val : arr) {
        int r = ((val % k) + k) % k; // handle negative numbers
        remCount[r]++;
    }
    // Remainder 0 elements must be paired among themselves
    if (remCount[0] % 2 != 0) {
        return false;
    }
    // For each remainder r from 1 to k/2, ensure counts match with complementary remainder
    for (int r = 1; r <= k / 2; r++) {
        if (r * 2 == k) { // middle remainder when k is even
            if (remCount[r] % 2 != 0) {
                return false;
            }
        } else {
            if (remCount[r] != remCount[k - r]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        // Invalid input: null array or non-positive divisor
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        // Cannot pair all elements if count is odd
        return false;
    }
    // Frequency of each remainder modulo k
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k; // handle negative numbers
        }
        freq[r]++;
    }
    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    // For all other remainders, counts must match complementary remainders
    for (int r = 1; r < k; r++) {
        // Skip complementary already checked to avoid double-check
        if (r > k - r) {
            break;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

