public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Validate input
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Build adjacency list
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) continue;
        int u = edge[0], v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        graph[u].add(v);
        graph[v].add(u);
    }

    int[] totalTime = new int[1];
    dfs(0, -1, graph, hasApple, totalTime);
    return totalTime[0];
}

private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] totalTime) {
    boolean hasAppleInSub = hasApple[node];
    for (int neighbor : graph[node]) {
        if (neighbor == parent) {
            continue;
        }
        if (dfs(neighbor, node, graph, hasApple, totalTime)) {
            totalTime[0] += 2; // go to child and back
            hasAppleInSub = true;
        }
    }
    return hasAppleInSub;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list for the tree
    List<List<Integer>> graph = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] e : edges) {
        int u = e[0];
        int v = e[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    // Use an array to hold the cumulative time, so it can be updated in recursion
    int[] time = new int[1];
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<List<Integer>> graph,
                    boolean[] hasApple, int[] time) {
    boolean hasAppleInSubtree = hasApple[node];
    for (int child : graph.get(node)) {
        if (child == parent) continue;
        boolean childHas = dfs(child, node, graph, hasApple, time);
        if (childHas) {
            // Need to traverse the edge twice (go and return)
            time[0] += 2;
            hasAppleInSubtree = true;
        }
    }
    return hasAppleInSubtree;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Validate inputs
    if (n <= 0 || hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input: number of nodes or hasApple array is incorrect");
    }
    if (edges == null || edges.length != Math.max(0, n - 1)) {
        throw new IllegalArgumentException("Invalid input: edges array length must be n-1 for a tree");
    }

    // Build adjacency list
    @SuppressWarnings("unchecked")
    ArrayList<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) {
            throw new IllegalArgumentException("Each edge must contain exactly two node indices");
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge node indices out of bounds");
        }
        adj[u].add(v);
        adj[v].add(u);
    }

    // Use iterative DFS to obtain traversal order and parent array
    int[] parent = new int[n];
    Arrays.fill(parent, -1);
    parent[0] = -2; // root has no parent
    int[] order = new int[n];
    int idx = 0;
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int neighbor : adj[node]) {
            if (parent[neighbor] == -1) {
                parent[neighbor] = node;
                stack.push(neighbor);
            }
        }
    }

    // Post-order processing to compute required time
    boolean[] hasAppleSub = new boolean[n];
    int time = 0;
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int child : adj[node]) {
            if (parent[child] == node) { // child in the DFS tree
                if (hasAppleSub[child]) {
                    time += 2;          // go to child and back
                    has = true;
                }
            }
        }
        hasAppleSub[node] = has;
    }

    return time;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch < 'a' || ch > 'z') {
            throw new IllegalArgumentException("Input string must contain only lowercase letters");
        }
        freq[ch - 'a']++;
    }
    int remaining = s.length();
    StringBuilder sb = new StringBuilder(remaining);
    while (remaining > 0) {
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    // Count occurrences of each lowercase letter
    int[] count = new int[26];
    for (char ch : s.toCharArray()) {
        if (ch >= 'a' && ch <= 'z') {
            count[ch - 'a']++;
        } else {
            // Ignore characters outside 'a'-'z'
            return ""; // or throw an exception if invalid input is not allowed
        }
    }

    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();

    while (remaining > 0) {
        // Ascending pass: smallest to largest
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
        // Descending pass: largest to smallest
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    char[] arr = s.toCharArray();
    java.util.Arrays.sort(arr);
    int low = 0;
    int high = arr.length - 1;
    StringBuilder result = new StringBuilder(arr.length);

    while (low <= high) {
        // Ascending phase
        char last = 0;
        while (low <= high) {
            if (arr[low] > last) {
                result.append(arr[low]);
                last = arr[low];
            }
            low++;
        }

        // Descending phase
        if (low <= high) { // high already decremented after moving past low
            // After ascending loop, low == high + 1, so set high = low - 1
            high = low - 1;
        } else {
            high = arr.length - 1;
        }
        if (low <= high) {
            result.append(arr[high]);
            last = arr[high];
            high--;
        }

        while (low <= high) {
            if (arr[high] < last) {
                result.append(arr[high]);
                last = arr[high];
            }
            high--;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    @SuppressWarnings("unchecked")
    java.util.HashSet<Long>[] dp = (java.util.HashSet<Long>[]) new java.util.HashSet[n + 1];
    dp[0] = new java.util.HashSet<>();
    dp[0].add(0L);

    int processed = 0;
    for (int num : nums) {
        // Update dp from higher subset sizes to avoid reuse of the same element
        for (int k = Math.min(processed, n - 1); k >= 1; k--) {
            java.util.HashSet<Long> prevSet = dp[k - 1];
            if (prevSet == null || prevSet.isEmpty()) {
                continue;
            }
            java.util.HashSet<Long> currentSet = dp[k];
            if (currentSet == null) {
                currentSet = new java.util.HashSet<>();
                dp[k] = currentSet;
            }
            for (long s : prevSet) {
                currentSet.add(s + num);
            }
        }
        processed++;
    }

    for (int k = 1; k <= n - 1; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        long target = (totalSum * k) / n;
        java.util.HashSet<Long> setK = dp[k];
        if (setK != null && setK.contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    // dp[k] holds all possible sums using exactly k numbers.
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0);

    for (int num : nums) {
        // Update in reverse order to avoid reuse of the same element.
        for (int k = n - 1; k >= 1; k--) {
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }

    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) return false;
    int n = nums.length;
    int total = 0;
    for (int num : nums) total += num;
    int maxK = n / 2;
    // table of sums for each subset size up to maxK
    @SuppressWarnings("unchecked")
    Set<Integer>[] sums = new HashSet[maxK + 1];
    for (int k = 0; k <= maxK; k++) sums[k] = new HashSet<>();
    sums[0].add(0);

    int processed = 0;
    for (int num : nums) {
        processed++;
        int upper = Math.min(maxK, processed);
        for (int k = upper; k >= 1; k--) {
            // iterate over a snapshot to avoid concurrent modification
            for (int s : new HashSet<>(sums[k - 1])) {
                sums[k].add(s + num);
            }
        }
    }

    for (int k = 1; k <= maxK; k++) {
        if ((total * k) % n == 0) {
            int target = (total * k) / n;
            if (sums[k].contains(target)) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    long totalSumLong = 0;
    for (int v : nums) {
        totalSumLong += v;
    }
    // Try all possible subset sizes k ( 1 <= k <= n/2 )
    for (int k = 1; k <= n / 2; k++) {
        long prod = totalSumLong * k;
        if (prod % n != 0) {
            continue; // target not an integer
        }
        int target = (int) (prod / n);
        // DP array: dp[i][s] = can we get sum s using i numbers?
        // We only need to track sums up to target
        boolean[][] dp = new boolean[k + 1][target + 1];
        dp[0][0] = true;
        for (int num : nums) {
            // No point processing num > target
            if (num > target) {
                continue;
            }
            // Update dp in reverse order to avoid reuse of the same element
            for (int i = k; i >= 1; i--) {
                for (int s = target; s >= num; s--) {
                    if (dp[i - 1][s - num]) {
                        dp[i][s] = true;
                    }
                }
            }
        }
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

