public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    // Validate input
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // Use two variables to store the cost of reaching the two previous steps.
    int prev2 = 0; // cost to reach step -1 (starting point before step 0)
    int prev1 = 0; // cost to reach step 0
    for (int i = 2; i <= n; i++) {
        // The cost to reach step i is the minimal cost to reach either of the two
        // previous steps plus the cost of the step just before the top.
        int curr = Math.min(prev1, prev2) + cost[i - 1];
        prev2 = prev1;
        prev1 = curr;
    }
    // prev1 now holds the minimal cost to reach the top.
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }

    int n = cost.length;
    // Use two variables to keep the minimal cost to reach step i-2 and i-1
    int dpPrev2 = 0; // cost to reach step i-2
    int dpPrev1 = 0; // cost to reach step i-1

    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = dpPrev1 + cost[i - 1];       // step from i-1
        int costFromPrev2 = dpPrev2 + cost[i - 2];       // step from i-2
        int curr = Math.min(costFromPrev1, costFromPrev2);

        // Shift for next iteration
        dpPrev2 = dpPrev1;
        dpPrev1 = curr;
    }

    return dpPrev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    int n = cost.length;
    if (n < 2) {
        // If there are fewer than 2 steps, the top is reachable without paying any cost.
        return 0;
    }
    // dp[i] represents the minimum cost to reach step i (0-indexed, with dp[0] and dp[1] meaning the start positions)
    long[] dp = new long[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        long costOneStep = dp[i - 1] + cost[i - 1];
        long costTwoSteps = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(costOneStep, costTwoSteps);
    }
    long result = dp[n];
    // Ensure the result fits into int range
    if (result > Integer.MAX_VALUE || result < Integer.MIN_VALUE) {
        throw new ArithmeticException("Result exceeds int range.");
    }
    return (int) result;
}

