    // Validate input
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null.");
    }
    if (k <= 0) {
        // There is exactly one binary string of length 0, the empty string,
        // which is trivially a substring of any string.
        return true;
    }
    // For k too large, the total number of possible codes (2^k) becomes
    // impractically large for memory allocation.  In typical usage k is
    // bounded (e.g., k <= 20).  We guard against overflow and avoid
    // allocating enormous arrays.
    if (k > 20) {
        // 2^k would be > 1,048,576, which is usually too big for an
        // array in this context.  Returning false indicates that we
        // cannot verify all codes under these constraints.
        return false;
    }

    int n = s.length();
    if (n < k) {
        return false;
    }

    int total = 1 << k;          // number of distinct binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;        // keep only the lower k bits
    int current = 0;
    int count = 0;

    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            throw new IllegalArgumentException("String contains non-binary character.");
        }
        // Build the integer representation of the current k-bit window.
        current = ((current << 1) & mask) | (c - '0');
        if (i >= k - 1) {
            // We have formed a complete substring of length k.
            if (!seen[current]) {
                seen[current] = true;
                count++;
                if (count == total) {
                    return true; // all possible codes found
                }
            }
        }
    }

    return false; // not all codes were present
}

