public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0;      // Number of unmatched '(' encountered
    int insertions = 0;   // Number of insertions needed so far
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // Need to insert a '(' before this ')'
                insertions++;
            } else {
                // Pair this ')' with a previous '('
                balance--;
            }
        }
        // Any other character is ignored as per problem statement
    }
    // Remaining unmatched '(' need a ')' each
    return insertions + balance;
}

