        long maxAbs = Math.max(maxSoFar, Math.abs(minSoFar));
        // Cast to int; result should fit within int bounds for typical inputs
        return (int) maxAbs;
    } catch (Exception e) {
        // In case of any runtime issue, return 0 as a safe default
        return 0;
    }
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    long maxEnding = nums[0];
    long maxSum = nums[0];
    long minEnding = nums[0];
    long minSum = nums[0];

    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];

        // Update maximum subarray ending here
        if (maxEnding + val > val) {
            maxEnding = maxEnding + val;
        } else {
            maxEnding = val;
        }
        if (maxEnding > maxSum) {
            maxSum = maxEnding;
        }

        // Update minimum subarray ending here
        if (minEnding + val < val) {
            minEnding = minEnding + val;
        } else {
            minEnding = val;
        }
        if (minEnding < minSum) {
            minSum = minEnding;
        }
    }

    long maxAbs = Math.abs(maxSum);
    long minAbs = Math.abs(minSum);
    return (int) Math.max(maxAbs, minAbs);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int n = fibs.size();
        int next = fibs.get(n - 1) + fibs.get(n - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    // Greedy subtraction
    int count = 0;
    int remaining = k;
    int i = fibs.size() - 1;
    while (remaining > 0) {
        if (fibs.get(i) <= remaining) {
            remaining -= fibs.get(i);
            count++;
        } else {
            i--;
        }
    }
    return count;
}

