public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int limit = (int) Math.sqrt(n);
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int pair = n / i;
            if (pair != i) {
                large.add(pair);
            }
        }
    }
    // big factors are currently in arbitrary order; we need them in ascending order.
    java.util.Collections.sort(large);
    // Merge lists in ascending order
    java.util.List<Integer> all = new java.util.ArrayList<>(small.size() + large.size());
    for (int val : small) {
        all.add(val);
    }
    for (int val : large) {
        all.add(val);
    }
    // Now all is sorted ascending.
    if (k > all.size()) {
        return -1;
    }
    return all.get(k - 1);
}

