    if (k > total) {
        return -1;
    }

    if (k <= small.size()) {
        return small.get(k - 1);
    }

    int remaining = k - small.size(); // 1-based index into reversed 'large'
    int idx = large.size() - remaining; // 0-based index
    return large.get(idx);
}

public String makeGood(String s) {
    if (s == null) return null;
    int n = s.length();
    char[] stack = new char[n];
    int stackSize = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (stackSize > 0 && Math.abs(c - stack[stackSize - 1]) == 32) {
            stackSize--; // remove the bad pair
        } else {
            stack[stackSize++] = c;
        }
    }
    return new String(stack, 0, stackSize);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    char[] stack = new char[n];
    int top = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (top > 0 && Character.toUpperCase(c) == Character.toUpperCase(stack[top - 1]) && c != stack[top - 1]) {
            top--; // remove the pair
        } else {
            stack[top++] = c;
        }
    }
    return new String(stack, 0, top);
}

public String makeGood(String s) {
    // Handle null input gracefully
    if (s == null) {
        return "";
    }

    // Use StringBuilder as a stack to build the resulting good string
    StringBuilder sb = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        // If the stack is not empty and the current character
        // forms an adjacent pair with the top of the stack
        // that is the same letter in different cases,
        // remove the top element (i.e., cancel the pair)
        if (sb.length() > 0) {
            char top = sb.charAt(sb.length() - 1);
            // Difference of 32 in ASCII represents opposite cases of the same letter
            if (Math.abs(c - top) == 32) {
                sb.deleteCharAt(sb.length() - 1);
                continue;
            }
        }

        // Otherwise, push the current character onto the stack
        sb.append(c);
    }

    return sb.toString();
}

