            if (c != top && Character.toLowerCase(c) == Character.toLowerCase(top)) {
                stack.deleteCharAt(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    return dfs(s, 0, new java.util.HashSet<String>());
}

private int dfs(String s, int start, java.util.Set<String> seen) {
    if (start == s.length()) {
        return seen.size();
    }
    int max = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String sub = s.substring(start, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int val = dfs(s, end, seen);
            if (val > max) {
                max = val;
            }
            seen.remove(sub);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int[] result = new int[1];
    try {
        dfs(s, 0, new java.util.HashSet<>(), 0, result);
    } catch (Exception e) {
        // In case of any unexpected runtime exception, return 0
        return 0;
    }
    return result[0];
}

private void dfs(String s, int index, java.util.Set<String> used, int count, int[] maxCount) {
    int n = s.length();
    if (index == n) {
        if (count > maxCount[0]) {
            maxCount[0] = count;
        }
        return;
    }
    for (int end = index + 1; end <= n; end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, end, used, count + 1, maxCount);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    return backtrack(0, s, new java.util.HashSet<String>());
}

private int backtrack(int index, String s, java.util.Set<String> used) {
    int n = s.length();
    if (index == n) {
        return 0;
    }
    int maxCount = 0;
    for (int end = index + 1; end <= n; end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int current = 1 + backtrack(end, s, used);
            if (current > maxCount) {
                maxCount = current;
            }
            used.remove(sub);
        }
    }
    return maxCount;
}

