private int dfs(String s, int idx, java.util.HashSet<String> seen) {
    int n = s.length();
    if (idx == n) {
        return 0;
    }
    int max = 0;
    for (int end = idx; end < n; end++) {
        String sub = s.substring(idx, end + 1);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int current = 1 + dfs(s, end + 1, seen);
            if (current > max) {
                max = current;
            }
            seen.remove(sub);
        }
    }
    return max;
}

