private int dfs(String s, int idx, java.util.Set<String> used) {
    int n = s.length();
    if (idx == n) {
        return 0;
    }
    int max = 0;
    for (int end = idx + 1; end <= n; end++) {
        String part = s.substring(idx, end);
        if (!used.contains(part)) {
            used.add(part);
            int cur = 1 + dfs(s, end, used);
            if (cur > max) {
                max = cur;
            }
            used.remove(part);
        }
    }
    return max;
}

public int minOperations(String[] logs) {
    if (logs == null) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue; // ignore
        }
        switch (log) {
            case "../":
                if (depth > 0) {
                    depth--;
                }
                break;
            case "./":
                // stay in the current directory
                break;
            default:
                // any other string is treated as entering a folder
                // we assume a valid folder is represented by a name ending with '/'
                if (log.endsWith("/")) {
                    depth++;
                }
                // if the format is invalid we ignore it
                break;
        }
    }
    return depth;
}

