public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) {
        return result;
    }
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.LinkedList<Integer> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i > high) {
            break;
        }
        queue.offer(i);
    }
    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        if (num <= high / 10) {
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                int nextNum = num * 10 + (lastDigit - 1);
                if (nextNum <= high) {
                    queue.offer(nextNum);
                }
            }
            if (lastDigit < 9) {
                int nextNum = num * 10 + (lastDigit + 1);
                if (nextNum <= high) {
                    queue.offer(nextNum);
                }
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

