    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();

        if (num > high) {
            continue;
        }

        if (num >= low) {
            result.add((int) num);
        }

        int lastDigit = (int) (num % 10);

        // Generate next stepping numbers by appending lastDigit-1 or lastDigit+1
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }

        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

