public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int n = A.length;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    boolean[] used = new boolean[n];
    return dfs(0, -1, used, arr);
}

private static int dfs(int depth, int lastIdx, boolean[] used, int[] arr) {
    int n = arr.length;
    if (depth == n) {
        return 1;
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (used[i]) {
            continue;
        }
        // Skip duplicates to avoid counting identical permutations
        if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) {
            continue;
        }
        if (lastIdx != -1) {
            int sum = arr[lastIdx] + arr[i];
            int root = (int) Math.sqrt(sum);
            if (root * root != sum) {
                continue;
            }
        }
        used[i] = true;
        count += dfs(depth + 1, i, used, arr);
        used[i] = false;
    }
    return count;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null) {
        throw new IllegalArgumentException("heights array cannot be null");
    }
    int n = heights.length;
    if (n == 0) {
        return 0;
    }
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0;
    for (int i = 0; i <= n; i++) {
        long curHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && heights[stack.peek()] >= curHeight) {
            int h = heights[stack.pop()];
            int left = stack.isEmpty() ? -1 : stack.peek();
            long width = i - left - 1;
            long area = (long) h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        if (i < n) {
            stack.push(i);
        }
    }
    return (int) maxArea;
}

