        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return new int[0];
    }
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    try {
        for (int sum = 0; sum <= m + n - 2; sum++) {
            if (sum % 2 == 0) {
                int i = Math.min(sum, m - 1);
                int j = sum - i;
                while (i >= 0 && j < n) {
                    result[idx++] = mat[i][j];
                    i--;
                    j++;
                }
            } else {
                int j = Math.min(sum, n - 1);
                int i = sum - j;
                while (j >= 0 && i < m) {
                    result[idx++] = mat[i][j];
                    i++;
                    j--;
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected error, return an empty array
        return new int[0];
    }
    return result;
}

