    int idx = 0;

    // The sum of indices (row + col) of each diagonal ranges from 0 to m+n-2
    for (int k = 0; k <= m + n - 2; k++) {
        if (k % 2 == 0) {
            // Even diagonals: start from the bottom of the diagonal and move up-right
            int row = Math.min(k, m - 1);
            int col = k - row;
            while (row >= 0 && col < n) {
                result[idx++] = mat[row][col];
                row--;
                col++;
            }
        } else {
            // Odd diagonals: start from the leftmost element of the diagonal and move down-left
            int col = Math.min(k, n - 1);
            int row = k - col;
            while (col >= 0 && row < m) {
                result[idx++] = mat[row][col];
                row++;
                col--;
            }
        }
    }
    return result;
}

