public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    // Check for empty rows
    if (n == 0) {
        return new int[0];
    }
    // Ensure all rows have the same length for valid rectangular matrix
    for (int i = 1; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows in the matrix must have the same length.");
        }
    }

    int total = m * n;
    int[] result = new int[total];
    int index = 0;

    // Iterate over all possible diagonals (sum of indices)
    for (int diag = 0; diag <= m + n - 2; diag++) {
        int startRow = Math.min(diag, m - 1);
        int endRow = Math.max(0, diag - (n - 1));

        if (diag % 2 == 0) { // even diagonal: bottom to top
            for (int row = startRow; row >= endRow; row--) {
                int col = diag - row;
                result[index++] = mat[row][col];
            }
        } else { // odd diagonal: top to bottom
            for (int row = endRow; row <= startRow; row++) {
                int col = diag - row;
                result[index++] = mat[row][col];
            }
        }
    }
    return result;
}

