    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Step 4: reverse the suffix starting at pivot+1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Reconstruct the number and check for overflow
    try {
        int result = Integer.parseInt(new String(digits));
        if (result > n) {
            return result;
        } else {
            return -1;
        }
    } catch (NumberFormatException e) {
        // In case the number exceeds integer bounds
        return -1;
    }
}

