private static void buildStrobogrammatic(int n, int left, int right, char[] current, List<String> result) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    if (left == right) {
        for (char c : new char[]{'0', '1', '8'}) {
            current[left] = c;
            buildStrobogrammatic(n, left + 1, right - 1, current, result);
        }
        return;
    }
    // Pairs: (0,0), (1,1), (6,9), (8,8), (9,6)
    for (int i = 0; i < 5; i++) {
        char a = "01189".charAt(i); // left digit
        char b = "01986".charAt(i); // right digit
        if (left == 0 && a == '0' && n > 1) {
            continue; // skip leading zero for numbers > 1 digit
        }
        current[left] = a;
        current[right] = b;
        buildStrobogrammatic(n, left + 1, right - 1, current, result);
    }
}

