private static List<String> generate(int currLen, int targetLen) {
    List<String> res = new ArrayList<>();
    if (currLen == 0) {
        res.add("");
        return res;
    }
    if (currLen == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> inner = generate(currLen - 2, targetLen);
    for (String s : inner) {
        if (currLen == targetLen) {
            res.add("1" + s + "1");
            res.add("6" + s + "9");
            res.add("8" + s + "8");
            res.add("9" + s + "6");
        } else {
            res.add("0" + s + "0");
            res.add("1" + s + "1");
            res.add("6" + s + "9");
            res.add("8" + s + "8");
            res.add("9" + s + "6");
        }
    }
    return res;
}

