    return result;
}

private static void generate(List<String> result, char[] str, int left, int right, int totalLen, char[][] pairs) {
    if (left > right) {
        // reject leading zero for numbers longer than 1 digit
        if (totalLen > 1 && str[0] == '0') {
            return;
        }
        result.add(new String(str));
        return;
    }

    if (left == right) {
        // middle digit for odd length
        char[] middleOptions = {'0', '1', '8'};
        for (char c : middleOptions) {
            str[left] = c;
            generate(result, str, left + 1, right - 1, totalLen, pairs);
        }
        return;
    }

    for (char[] pair : pairs) {
        if (left == 0 && pair[0] == '0') {
            // skip numbers with leading zero unless the number is a single digit
            continue;
        }
        str[left] = pair[0];
        str[right] = pair[1];
        generate(result, str, left + 1, right - 1, totalLen, pairs);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];
    if (p1 == null || p2 == null || p3 == null) {
        return false;
    }
    if (p1.length < 2 || p2.length < 2 || p3.length < 2) {
        return false;
    }
    long x1 = p1[0], y1 = p1[1];
    long x2 = p2[0], y2 = p2[1];
    long x3 = p3[0], y3 = p3[1];
    long area = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return area != 0;
}

