        long x2 = points[1][0], y2 = points[1][1];
        long x3 = points[2][0], y3 = points[2][1];
        long cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        return cross != 0;
    } catch (Exception e) {
        // In case of any runtime exception (e.g., array index issues), treat as not a boomerang
        return false;
    }
}

