public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = n; // maximum possible when using 1^2
        int limit = (int) Math.sqrt(i);
        for (int j = 1; j <= limit; j++) {
            int sq = j * j;
            int candidate = dp[i - sq] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = i; // worst case, all 1^2
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int value = dp[i - square] + 1;
            if (value < min) {
                min = value;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Handle non‑positive input gracefully
    if (n <= 0) {
        return 0;
    }

    try {
        // dp[i] will hold the minimum count of perfect squares that sum to i
        int[] dp = new int[n + 1];
        // Initialize dp[0] = 0 and other values to a large number
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            dp[i] = Integer.MAX_VALUE;
            // Try all possible squares that are <= i
            for (int j = 1; j * j <= i; j++) {
                int square = j * j;
                if (dp[i] > dp[i - square] + 1) {
                    dp[i] = dp[i - square] + 1;
                }
            }
        }
        return dp[n];
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return -1 to indicate failure
        return -1;
    }
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    int maxRoot = (int)Math.sqrt(n);
    int[] squares = new int[maxRoot];
    for (int i = 1; i <= maxRoot; i++) {
        squares[i - 1] = i * i;
    }
    for (int i = 1; i <= n; i++) {
        for (int s : squares) {
            if (s > i) {
                break;
            }
            int candidate = dp[i - s] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int length = s.length();
    int i = 0;
    while (i < length) {
        char current = s.charAt(i);
        if (current == ' ') {
            result.append(' ');
            i++;
        } else {
            int start = i;
            while (i < length && s.charAt(i) != ' ') {
                i++;
            }
            String word = s.substring(start, i);
            result.append(new StringBuilder(word).reverse());
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    int n = s.length();
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            result.append(' ');
            word.setLength(0);
        } else {
            word.append(c);
        }
    }
    // Append the last word after loop
    result.append(word.reverse());
    return result.toString();
}

